// Selko Comply — Clinical Documentation Training Modules
// Adds: OASIS Start of Care, OASIS Recertification, OASIS Discharge,
//       Therapy Re-Evaluation, Daily Visit Notes
// Loaded after selko-comply-modules.js; pushes onto the shared MODULES array.
// OASIS content is based on the CMS OASIS-E2 Guidance Manual (effective April 1, 2026).
// Version: 1.0 | Updated: Oct 25, 2026

(function () {
  if (typeof MODULES === 'undefined') { console.warn('Clinical modules: MODULES not found'); return; }

  const CLINICAL_MODULES = [

    // ─────────────────────────────────────────────
    // 1. OASIS START OF CARE
    // ─────────────────────────────────────────────
    {
      id: 'oasis_soc',
      disciplines: ['PT','OT','SLP','RN'],
      track: ['newhire', 'annual'],
      icon: '📝',
      title: 'OASIS-E2: Start of Care Assessment',
      desc: 'Who completes the SOC OASIS, the 5-day window, core coding rules, function and falls items, and how to finish and sign accurately.',
      passScore: 80,
      mins: 20,
      staffTypes: ['clinician', 'owner', 'admin', 'office'],
      slides: [
        { title: 'Why the Start of Care OASIS Matters', content: `<p>The OASIS is a standard set of data items that home health agencies build into the comprehensive assessment. The Start of Care (SOC) assessment sets the baseline for the whole episode.</p><ul><li><strong>Quality:</strong> your baseline is compared with discharge to measure patient outcomes</li><li><strong>Payment:</strong> function items help set the Medicare payment group</li><li><strong>Care planning:</strong> the assessment is the basis of the physician-ordered plan of care</li><li><strong>Legal record:</strong> your signature attests that every response reflects the patient's status as assessed</li></ul><div class="callout">This module follows the CMS OASIS-E2 Guidance Manual, effective April 1, 2026. OASIS is not a full assessment by itself. It sits inside your agency's comprehensive assessment.</div><div style="background:var(--surface);border:1px solid var(--border);border-left:4px solid var(--navy2);border-radius:8px;padding:12px 16px;margin:14px 0"><strong>Examples</strong><ul style="margin:8px 0 0 18px"><li style="margin-bottom:6px"><strong>Baseline vs. outcome:</strong> at SOC a patient needs hands-on help to rise from a chair and walks 25 ft with a walker. At discharge the patient rises with supervision and walks 150 ft. The comparison only means something if the SOC entry was observed and accurate.</li><li style="margin-bottom:6px"><strong>Inflated baseline:</strong> if the SOC records the patient as needing less help than the patient really needed, later gains look small. If it records more help than needed, the agency can look as if it delivered more than it did. Both distort the picture.</li></ul></div>` },
        { title: 'Who Completes the SOC OASIS and When', content: `<p>The SOC assessment must be completed <strong>within 5 calendar days after the SOC date</strong>, counting the SOC date as day 0.</p><ul><li>Only an <strong>RN, PT, OT or SLP</strong> may be responsible for the comprehensive assessment and OASIS</li><li><strong>PTAs, COTAs, LPNs, social workers and aides may not</strong>, but they can pass observations to the assessing clinician</li><li>When <strong>nursing and PT are both ordered</strong> at referral, the RN must do the SOC assessment</li><li>When <strong>PT is the only service ordered</strong>, the PT may do the initial assessment visit and the SOC comprehensive assessment</li></ul><div class="callout warn">The SOC date is the date of the first <strong>reimbursable</strong> service. A visit made only to do the assessment does not set the SOC date, and an assessment completed before the SOC date does not meet the Conditions of Participation.</div><div style="background:var(--surface);border:1px solid var(--border);border-left:4px solid var(--navy2);border-radius:8px;padding:12px 16px;margin:14px 0"><strong>Examples</strong><ul style="margin:8px 0 0 18px"><li style="margin-bottom:6px"><strong>Nursing and PT both ordered:</strong> the referral orders SN and PT after a stroke. The RN completes the SOC comprehensive assessment and OASIS. The PT completes the PT evaluation and shares function findings with the RN.</li><li style="margin-bottom:6px"><strong>PT-only order:</strong> a patient is referred for PT only after a hip replacement and PT establishes eligibility for the payer. The PT can do the initial assessment visit, the SOC comprehensive assessment and the OASIS.</li><li style="margin-bottom:6px"><strong>Counting the 5 days:</strong> SOC date is Wednesday (day 0). The OASIS must be complete by the following Monday (day 5).</li><li style="margin-bottom:6px"><strong>Nursing ordered but not needed:</strong> the RN's first visit finds the patient needs no nursing and declines it. That visit does not set the SOC date. The PT's first billable visit does. The RN can return within 5 days for a non-billable visit to finish the OASIS, or the PT can complete it.</li><li style="margin-bottom:6px"><strong>Which date is the SOC date?</strong> an RN does a non-billable assessment visit Monday. The PT's first billable visit is Wednesday. The SOC date is Wednesday.</li></ul></div>` },
        { title: 'Before You Walk In', content: `<p>Preparation prevents most SOC errors.</p><ul><li>Confirm the physician or allowed practitioner order and the ordered SOC date</li><li>If no specific start date was ordered, the initial contact must happen within <strong>48 hours</strong> of the referral</li><li>Confirm your discipline is allowed to be the assessing clinician for this patient</li><li>Know which payer the agency will bill. Under the all-payer rule, OASIS is required for patients with any pay source who receive skilled services, with a few exemptions (under 18, maternity care, personal care only)</li><li>Have the OASIS privacy notice ready. Patients with OASIS collected must be given the Statement of Patient Privacy Rights and the Privacy Act Statement</li></ul><div class="callout">Clerical staff may enter name, birth date or Medicare number first, but you must verify them when you complete the assessment.</div><div style="background:var(--surface);border:1px solid var(--border);border-left:4px solid var(--navy2);border-radius:8px;padding:12px 16px;margin:14px 0"><strong>Examples</strong><ul style="margin:8px 0 0 18px"><li style="margin-bottom:6px"><strong>No start date ordered:</strong> the referral arrives Monday at 8 a.m. with no ordered SOC date. The initial contact must happen within 48 hours, so by Wednesday at 8 a.m.</li><li style="margin-bottom:6px"><strong>All-payer rule:</strong> a self-pay patient receives skilled PT in the home. OASIS is required. A 16-year-old receiving skilled PT is exempt because OASIS does not apply to patients under 18.</li><li style="margin-bottom:6px"><strong>Privacy notice:</strong> before you start the OASIS items, give the patient the Statement of Patient Privacy Rights and the Privacy Act Statement, available in English and Spanish.</li><li style="margin-bottom:6px"><strong>Verify clerical entries:</strong> intake typed the patient's Medicare number. You compare it with the card in the home before signing.</li></ul></div>` },
        { title: 'Core Coding Rules Every Clinician Must Know', content: `<ul><li><strong>Day of assessment</strong> means the 24 hours before your visit plus the time you are in the home</li><li>If the patient varies during that day, code what is true <strong>more than 50% of the time</strong></li><li>For function and physiological status, <strong>direct observation</strong> is the preferred method. Do not copy status from a hospital or prior setting</li><li><strong>Assistance means help from another person</strong>, including verbal cues and supervision, not only touch</li><li>Software cannot choose the code. <strong>You are responsible</strong> for every response</li><li>Minimize NA and Unknown. A <strong>dash</strong> means no information is available and is expected to be rare. It is valid only on items that allow it</li><li>Follow skip patterns and use the item definitions exactly</li></ul><div class="callout danger">Never carry codes forward from a prior assessment. Every OASIS time point must reflect a fresh assessment of the patient.</div><div style="background:var(--surface);border:1px solid var(--border);border-left:4px solid var(--navy2);border-radius:8px;padding:12px 16px;margin:14px 0"><strong>Examples</strong><ul style="margin:8px 0 0 18px"><li style="margin-bottom:6px"><strong>Day of assessment:</strong> your visit is Tuesday 2 p.m. to 3 p.m. The day of assessment runs from Monday 2 p.m. through the end of your visit Tuesday at 3 p.m.</li><li style="margin-bottom:6px"><strong>More than 50% rule:</strong> a patient manages the bathroom alone during most of the day but needs help getting up at night. Code what is true more than half of that time period and document both observations.</li><li style="margin-bottom:6px"><strong>Assistance includes cues:</strong> a patient can do the task alone but only after reminders to lock the walker and slow down. That counts as assistance, because verbal cues and supervision count.</li><li style="margin-bottom:6px"><strong>Observe, don't copy:</strong> the hospital discharge summary says the patient was independent with transfers. You watch the patient and see stand-by help needed. Code what you saw.</li><li style="margin-bottom:6px"><strong>Dash use:</strong> do not use a dash because an item was inconvenient to assess. Use it only on items that allow it, when truly no information is available.</li></ul></div>` },
        { title: 'Function Items: M1800 Series and Section GG', content: `<p>Function items are the ones PTs are most often asked to weigh in on.</p><p><strong>M1800-series ADL/IADL items</strong></p><ul><li>Code the patient's <strong>ability</strong> to do the task safely, not preference or willingness</li><li>Ability includes the level of cueing, supervision or stand-by help needed</li><li>A caregiver being present or absent does not change the code</li><li>If ability varies across tasks inside one item, code what is true for most included tasks, giving more weight to tasks done more often</li><li>Consider ordered activity restrictions</li></ul><p><strong>GG0130 Self-Care and GG0170 Mobility</strong></p><ul><li>Coded from a functional assessment done at or soon after SOC</li><li>The scale runs from 06 independent down to 01 dependent, with separate codes for activities not attempted</li><li>Record what the patient did, how many attempts, and the help needed, so your code can be defended from your note</li></ul><div class="callout warn">The same patient can code differently on an M1800 item and a GG item because each item has its own inclusions, exclusions and device rules. Code each item on its own guidance.</div><div style="background:var(--surface);border:1px solid var(--border);border-left:4px solid var(--navy2);border-radius:8px;padding:12px 16px;margin:14px 0"><strong>Examples</strong><ul style="margin:8px 0 0 18px"><li style="margin-bottom:6px"><strong>Ability vs. preference:</strong> a patient could bathe safely with set-up help but prefers that a daughter do it. Code the patient's ability, not the preference.</li><li style="margin-bottom:6px"><strong>Caregiver presence:</strong> a patient's spouse always helps with dressing, but the patient could dress with supervision alone. Code the level of help the patient needs to do the task safely, not the help that happens to be given.</li><li style="margin-bottom:6px"><strong>Multi-task item:</strong> a patient manages one task in the item alone but needs help with the more frequently done tasks. Weight the tasks done more often.</li><li style="margin-bottom:6px"><strong>Activity restrictions:</strong> the physician ordered non-weight-bearing on the left leg. Consider that restriction when you judge ambulation and transfer ability.</li><li style="margin-bottom:6px"><strong>GG documentation example:</strong> &ldquo;Sit to stand from standard chair: 2 attempts, trunk support needed to rise both times. Walked 10 ft with rolling walker, contact guard, cue for walker placement on first turn.&rdquo; The note shows what happened so the code can be defended.</li></ul></div>` },
        { title: 'Falls, Safety and Items That Get Missed', content: `<ul><li><strong>Falls (J1800/J1900):</strong> these items count falls since SOC/ROC. Ask about falls at every visit and check records for ER visits</li><li><strong>Major injury</strong> includes, but is not limited to, fractures, dislocations, internal organ injuries, amputations, spinal cord injuries, head injuries and crush injuries</li><li>A fall or an <strong>intercepted fall during intentional balance training</strong> that causes a major injury is reported as both a fall and a major injury</li><li><strong>Language and interpreter (A1110)</strong> and <strong>transportation (A1255)</strong> are collected at SOC and ROC</li><li>Hearing (B0200) and vision (B1000) must also be assessed. They were added to the ROC time point in OASIS-E2</li></ul><div class="callout">CMS reported that more than half of falls with major injury were not captured on OASIS. A direct question at every visit is the easiest fix.</div><div style="background:var(--surface);border:1px solid var(--border);border-left:4px solid var(--navy2);border-radius:8px;padding:12px 16px;margin:14px 0"><strong>Examples</strong><ul style="margin:8px 0 0 18px"><li style="margin-bottom:6px"><strong>Question to ask:</strong> &ldquo;Since I last saw you, have you fallen, slipped, or ended up on the floor, even if you were not hurt?&rdquo;</li><li style="margin-bottom:6px"><strong>Fall, no injury:</strong> a patient slides to the floor in the bathroom and gets up without help. It is still a fall.</li><li style="margin-bottom:6px"><strong>Injury, not major:</strong> a patient trips and gets a skin tear or bruise. Report the fall and the injury level as described in the manual.</li><li style="margin-bottom:6px"><strong>Major injury:</strong> a patient falls and fractures a wrist. That is a fall with major injury.</li><li style="margin-bottom:6px"><strong>Balance training:</strong> during a balance drill you intercept a fall and the patient fractures a rib. It is reported as both a fall and a major injury.</li><li style="margin-bottom:6px"><strong>Chart check:</strong> a neighbor mentions the ambulance came last week. Check the record for an ER visit and ask the patient about it.</li></ul></div>` },
        { title: 'Finishing the Assessment', content: `<ul><li><strong>M0090 Date Assessment Completed</strong> is the last date you gathered and documented information used for the OASIS. It can be a date with no visit, such as a call to the physician</li><li>Your <strong>signature is an attestation</strong> that the assessment, including each OASIS response, reflects the patient's status as supported by the record</li><li>Check that your OASIS, your evaluation and the plan of care agree. Auditors look for contradictions, such as independent walking on the OASIS and standby assist in your note</li><li>If collaboration was used, review what was gathered and make the final choice yourself</li><li>Errors found later are corrected by <strong>modification</strong> or <strong>inactivation</strong> records, and agencies have 24 months from the assessment target date to submit, modify or inactivate</li></ul><div class="callout">Single-visit stays: OASIS is not required for quality reporting, but it is required to bill Medicare under PDGM.</div><div style="background:var(--surface);border:1px solid var(--border);border-left:4px solid var(--navy2);border-radius:8px;padding:12px 16px;margin:14px 0"><strong>Examples</strong><ul style="margin:8px 0 0 18px"><li style="margin-bottom:6px"><strong>M0090 date:</strong> you complete the visit Monday, call the physician Wednesday to clarify an order, and finalize the OASIS Thursday. M0090 is Thursday, even though there was no visit that day.</li><li style="margin-bottom:6px"><strong>Contradiction caught before signing:</strong> the OASIS says the patient walks independently. Your evaluation says walker with contact guard. Fix the OASIS or explain the difference before you sign.</li><li style="margin-bottom:6px"><strong>Collaboration:</strong> a PTA observed the patient on stairs the day before your SOC. You review the PTA's note, decide the code yourself, and record that you used it.</li><li style="margin-bottom:6px"><strong>Late error:</strong> two weeks later you notice you coded a mobility item wrong. You follow the agency correction policy, and a modification record is sent if the OASIS was already submitted.</li></ul></div>` },
        { title: 'Worked Examples', content: `<p>Try each scenario before reading the answer.</p><div style="background:var(--surface);border:1px solid var(--border);border-radius:8px;padding:12px 16px;margin:10px 0"><p style="margin:0 0 6px"><strong>Scenario 1.</strong> The referral orders nursing and PT. You are the PT and arrive first on Monday. The RN is scheduled Tuesday.</p><p style="margin:0"><strong>What to do:</strong> The RN must complete the SOC comprehensive assessment and OASIS. You complete your PT evaluation and tell the RN what you observed about function.</p></div><div style="background:var(--surface);border:1px solid var(--border);border-radius:8px;padding:12px 16px;margin:10px 0"><p style="margin:0 0 6px"><strong>Scenario 2.</strong> PT is the only service ordered and your first billable visit is Wednesday.</p><p style="margin:0"><strong>What to do:</strong> The SOC date is Wednesday. The OASIS must be completed by the following Monday.</p></div><div style="background:var(--surface);border:1px solid var(--border);border-radius:8px;padding:12px 16px;margin:10px 0"><p style="margin:0 0 6px"><strong>Scenario 3.</strong> Your evaluation says the patient walks with a walker and contact guard. A draft OASIS says independent walking.</p><p style="margin:0"><strong>What to do:</strong> Do not sign. Reconcile the two so the OASIS matches what you observed.</p></div><div style="background:var(--surface);border:1px solid var(--border);border-radius:8px;padding:12px 16px;margin:10px 0"><p style="margin:0 0 6px"><strong>Scenario 4.</strong> The patient says that two days before the visit a fall happened and an ambulance came.</p><p style="margin:0"><strong>What to do:</strong> Document it in your evaluation and fall-risk assessment, record it with the agency's SOC fall history items, and let the case manager know. J1800 and J1900 count falls after SOC or ROC.</p></div><div style="background:var(--surface);border:1px solid var(--border);border-radius:8px;padding:12px 16px;margin:10px 0"><p style="margin:0 0 6px"><strong>Scenario 5.</strong> The patient is a self-pay 70-year-old receiving skilled PT.</p><p style="margin:0"><strong>What to do:</strong> OASIS is required, because the all-payer rule applies when skilled services are provided.</p></div>` },
        { title: 'Regulatory References', content: `<p>This module is based on:</p><ul><li><strong>CMS OASIS-E2 Guidance Manual</strong>, effective April 1, 2026 (Chapters 1 to 3)</li><li><strong>42 CFR 484.55</strong> — Condition of Participation: Comprehensive assessment of patients</li><li><strong>42 CFR 484.45</strong> — Condition of Participation: Reporting OASIS information</li></ul><div class="callout">Agency policy may be stricter than CMS guidance. Follow the written policy of the agency you are working for wherever the manual defers to agency policy.</div>` }
      ],
      quiz: [
        { q: 'A referral orders both nursing and PT. Who must complete the SOC comprehensive assessment and OASIS?', options: ['The PT, because therapy visits are longer', 'The RN', 'Any clinician who sees the patient first', 'The PTA, with PT co-signature'], answer: 1, explanation: 'When nursing and PT are both ordered at referral, the RN must perform the SOC comprehensive assessment including OASIS. An RN, PT, OT or SLP may do later assessments.' },
        { q: 'The SOC OASIS must be completed within:', options: ['48 hours of the referral', '5 calendar days after the SOC date', '10 business days after discharge from the hospital', '30 days after the first visit'], answer: 1, explanation: 'The SOC assessment is due within 5 calendar days after the SOC date, with the SOC date counted as day 0.' },
        { q: 'On the day of assessment the patient needs standby help on stairs most of the time but not on a good day. How do you code the item?', options: ['Code the best performance seen', 'Code the worst performance seen', 'Code what is true more than 50% of the time and document both observations', 'Leave a dash'], answer: 2, explanation: 'If status varies during the day of assessment, code what is true more than 50% of the time, unless the item says otherwise. Document what you saw.' },
        { q: 'Which of these may NOT be responsible for completing the comprehensive assessment and OASIS?', options: ['Physical therapist', 'Occupational therapist', 'Registered nurse', 'Physical therapist assistant'], answer: 3, explanation: 'PTAs, COTAs, LPNs, social workers and aides may not be responsible for the comprehensive assessment or OASIS. They may share observations with the assessing clinician.' },
        { q: 'During a balance drill a clinician intercepts a fall and the patient fractures a rib. How is this reported?', options: ['It is not a fall because it was intercepted', 'As a fall with a major injury in J1800 and J1900', 'As a minor injury only', 'Only in the visit note'], answer: 1, explanation: 'Under OASIS-E2, a fall or intercepted fall during intentionally challenged balance training that results in a major injury is reported as both a fall and a major injury.' }
      ]
    },

    // ─────────────────────────────────────────────
    // 2. OASIS RECERTIFICATION
    // ─────────────────────────────────────────────
    {
      id: 'oasis_recert',
      disciplines: ['PT','OT','SLP','RN'],
      track: ['newhire', 'annual'],
      icon: '🔁',
      title: 'OASIS-E2: Recertification (Follow-Up)',
      desc: 'The day 56-60 window, what a recert assessment must cover, what to do when it is missed, and how it interacts with ROC and other follow-up assessments.',
      passScore: 80,
      mins: 18,
      staffTypes: ['clinician', 'owner', 'admin', 'office'],
      slides: [
        { title: 'The Recertification Window', content: `<p>Every patient who remains on service must have a follow-up comprehensive assessment, including OASIS, during the <strong>last 5 days of each 60-day certification period</strong>. That is <strong>days 56 to 60</strong>.</p><ul><li>Reason for assessment on the OASIS is <strong>M0100 response 4, Recertification</strong></li><li>Days are counted from the <strong>original Start of Care date</strong>, not from a resumption of care date</li><li>You may start the assessment on day 56 and finish on or before day 60</li><li>The requirement repeats every 60 days until the patient is discharged</li></ul><div class="callout warn">The window is short. If the agency also tracks 30-day billing periods, do not confuse them with the 60-day recertification window.</div><div style="background:var(--surface);border:1px solid var(--border);border-left:4px solid var(--navy2);border-radius:8px;padding:12px 16px;margin:14px 0"><strong>Examples</strong><ul style="margin:8px 0 0 18px"><li style="margin-bottom:6px"><strong>Counting the dates:</strong> if the SOC date is Oct 1 and your system counts that as day 1, days 56 to 60 run Nov 25 to Nov 29. Always confirm the dates in your agency's tracker.</li><li style="margin-bottom:6px"><strong>Not from ROC:</strong> a patient was hospitalized and resumed care on day 44. The recert is still due on days 56 to 60 from the original SOC, not 60 days from the ROC.</li><li style="margin-bottom:6px"><strong>Starting early:</strong> you begin the assessment on day 56 and finish it on day 58. That is allowed.</li></ul></div>` },
        { title: 'What a Recertification Assessment Is', content: `<p>A recert is a full, fresh assessment, not a copy of the last one.</p><ul><li>You need an <strong>in-person visit</strong> with the patient</li><li>Responses are based on your observation and the patient's status on the day of assessment</li><li>It supports continued eligibility, updated goals and the plan of care for the next period</li><li>Compare current function with the prior assessment so progress, plateau or decline is clear</li><li>Only an <strong>RN, PT, OT or SLP</strong> may complete it. PTAs can contribute observations but not the assessment</li></ul><div class="callout">When nursing and therapy are both involved, agency policy decides who completes the recert. Confirm that before day 56 so the visit does not fall through the cracks.</div><div style="background:var(--surface);border:1px solid var(--border);border-left:4px solid var(--navy2);border-radius:8px;padding:12px 16px;margin:14px 0"><strong>Examples</strong><ul style="margin:8px 0 0 18px"><li style="margin-bottom:6px"><strong>Fresh assessment:</strong> at SOC the patient walked 25 ft with a walker and contact guard. At recert you watch the patient walk and record what you see, such as 150 ft with a walker and supervision. You do not copy the SOC entry.</li><li style="margin-bottom:6px"><strong>Progress statement:</strong> &ldquo;Since SOC, transfers improved from moderate assist to supervision, and gait distance improved from 25 ft to 150 ft. Patient continues to need skilled PT for stair training and balance progression.&rdquo;</li><li style="margin-bottom:6px"><strong>PTA contribution:</strong> a PTA sees the patient on day 55 and notes new unsteadiness. The PTA tells the PT, and the PT includes it in the assessment.</li></ul></div>` },
        { title: 'Scheduling It So It Is Not Missed', content: `<ul><li>Know each patient's day 56 date at the start of the period</li><li>If no visit is scheduled in days 56 to 60, a clinician can make a visit <strong>only to do the assessment</strong>. It is not billable unless skilled services are provided</li><li>If the patient declines a visit in the window, document it and complete the assessment as soon as possible afterward</li><li>When several disciplines see the patient, agree on one assessing clinician and share observations ahead of time</li></ul><div class="callout">A good habit: on the first visit of each period, write the day 56 to 60 dates in your notes or the agency's tracking tool.</div><div style="background:var(--surface);border:1px solid var(--border);border-left:4px solid var(--navy2);border-radius:8px;padding:12px 16px;margin:14px 0"><strong>Examples</strong><ul style="margin:8px 0 0 18px"><li style="margin-bottom:6px"><strong>Tracking habit:</strong> on the first visit of a period, write &ldquo;Recert days 56-60: Nov 25-29&rdquo; at the top of your notes or in the tracker.</li><li style="margin-bottom:6px"><strong>Therapy-only case:</strong> a PT sees the patient twice weekly. The PT does the recert at a regular treatment visit on day 58. That visit is still a billable skilled visit.</li><li style="margin-bottom:6px"><strong>No visit scheduled:</strong> a patient has no visit planned in days 56 to 60. A clinician can make a visit only to do the assessment. It is not billable unless skilled services are provided.</li><li style="margin-bottom:6px"><strong>Patient declines:</strong> a patient cancels every visit in the window. Document each attempt and the refusal, and complete the assessment as soon as the patient allows.</li></ul></div>` },
        { title: 'When the Window Is Missed', content: `<p>If the day 56 to 60 window passes without a recert assessment:</p><ul><li><strong>Do not discharge and readmit</strong> the patient with a new SOC</li><li>Send a clinician as soon as the miss is found</li><li>Enter the <strong>actual date</strong> the assessment is completed in M0090</li><li>Document in the clinical record why it was late</li><li>Expect a warning message on submission. It does not block transmission</li><li>Talk to the Medicare Administrative Contractor about payment effects</li></ul><div class="callout danger">A missed recert shows non-compliance with the comprehensive assessment update standard. Avoid it, and never hide it. Document it.</div><div style="background:var(--surface);border:1px solid var(--border);border-left:4px solid var(--navy2);border-radius:8px;padding:12px 16px;margin:14px 0"><strong>Examples</strong><ul style="margin:8px 0 0 18px"><li style="margin-bottom:6px"><strong>Found on day 63:</strong> you complete the assessment on day 63 or as soon as you can reach the patient. M0090 is the real completion date. Do not backdate it to day 60.</li><li style="margin-bottom:6px"><strong>Sample documentation:</strong> &ldquo;Recert due days 56-60 not completed because scheduling error identified on day 63. Assessment completed on [date]. Physician notified.&rdquo;</li><li style="margin-bottom:6px"><strong>What not to do:</strong> do not discharge the patient and admit again with a new SOC to fix a missed recert.</li></ul></div>` },
        { title: 'ROC and Other Follow-Up Assessments', content: `<p>The recert is not the only follow-up time point.</p><ul><li><strong>Resumption of Care (response 3):</strong> due within 2 calendar days after an inpatient stay of 24 hours or more. If the patient comes home during days 56 to 60, one ROC assessment can serve as both ROC and recert</li><li>If the 2 days after discharge fall <strong>before</strong> day 56, you need a ROC now and a recert later</li><li><strong>Other Follow-Up (response 5):</strong> due within 2 calendar days after a significant change in condition. CMS does not define significant, so <strong>your agency policy does</strong></li><li>ER visits and observation stays do not count as inpatient stays</li></ul><div class="callout">Know your agency's written definition of a major decline or improvement. That is the trigger for Other Follow-Up.</div><div style="background:var(--surface);border:1px solid var(--border);border-left:4px solid var(--navy2);border-radius:8px;padding:12px 16px;margin:14px 0"><strong>Examples</strong><ul style="margin:8px 0 0 18px"><li style="margin-bottom:6px"><strong>ROC doubles as recert:</strong> a patient is discharged from the hospital on day 54, and the ROC is done on day 56. The ROC can serve as both the resumption and the recertification assessment, with the physician in agreement.</li><li style="margin-bottom:6px"><strong>ROC and later recert:</strong> a patient is discharged on day 53 with no ordered ROC date. The ROC is due no later than day 55. The recert is still due in days 56 to 60.</li><li style="margin-bottom:6px"><strong>Other Follow-Up:</strong> a patient who was walking with a cane has a stroke at home on day 30 and now needs max assist to transfer. Under many agency policies that is a major decline, so an Other Follow-Up assessment is due within 2 calendar days.</li><li style="margin-bottom:6px"><strong>Not a hospital stay:</strong> an ER visit that ends the same night does not trigger a ROC.</li></ul></div>` },
        { title: 'Coding and Documentation Checklist', content: `<ul><li>Observe function yourself. Code M1800 and GG items on current status, not on the last assessment</li><li>Ask about falls and injuries since SOC/ROC, and review records for ER or hospital visits</li><li>Record what changed since the last assessment: function, pain, cognition, medications, caregiver support</li><li>Update goals and the plan of care to match findings</li><li>Set M0090 to the last date you gathered and documented the information</li><li>Sign only after reviewing every response, including anything collected by a PTA or nurse</li></ul><div class="callout warn">Check that the OASIS, your evaluation or re-evaluation, and your visit notes tell the same story. Contradictions are what auditors flag first.</div><div style="background:var(--surface);border:1px solid var(--border);border-left:4px solid var(--navy2);border-radius:8px;padding:12px 16px;margin:14px 0"><strong>Examples</strong><ul style="margin:8px 0 0 18px"><li style="margin-bottom:6px"><strong>Change summary line:</strong> &ldquo;Compared with SOC: pain down from 7/10 to 3/10, walking distance up from 25 ft to 150 ft, new fall on day 41 without injury, daughter now present afternoons.&rdquo;</li><li style="margin-bottom:6px"><strong>Consistency check:</strong> your recert says the patient needs supervision on stairs. Your last three visit notes say contact guard. Resolve the difference before signing.</li><li style="margin-bottom:6px"><strong>Plan update:</strong> goals met for transfers are closed. A new goal for community mobility is added with a target date.</li></ul></div>` },
        { title: 'Worked Examples', content: `<p>Try each scenario before reading the answer.</p><div style="background:var(--surface);border:1px solid var(--border);border-radius:8px;padding:12px 16px;margin:10px 0"><p style="margin:0 0 6px"><strong>Scenario 1.</strong> SOC was Oct 1. It is Nov 20 and no recert is scheduled.</p><p style="margin:0"><strong>What to do:</strong> Confirm days 56 to 60 in the tracker, schedule the visit, and plan the assessment inside the window. If no skilled visit is due, an assessment-only visit is allowed.</p></div><div style="background:var(--surface);border:1px solid var(--border);border-radius:8px;padding:12px 16px;margin:10px 0"><p style="margin:0 0 6px"><strong>Scenario 2.</strong> It is day 63 and the recert was never done.</p><p style="margin:0"><strong>What to do:</strong> Do not discharge and readmit. Complete the assessment now, enter the real date in M0090, and document why it was late.</p></div><div style="background:var(--surface);border:1px solid var(--border);border-radius:8px;padding:12px 16px;margin:10px 0"><p style="margin:0 0 6px"><strong>Scenario 3.</strong> A patient returns from the hospital on day 54 and ROC is done on day 56.</p><p style="margin:0"><strong>What to do:</strong> The ROC can serve as both ROC and recert if the physician agrees.</p></div><div style="background:var(--surface);border:1px solid var(--border);border-radius:8px;padding:12px 16px;margin:10px 0"><p style="margin:0 0 6px"><strong>Scenario 4.</strong> A patient's function drops sharply on day 30.</p><p style="margin:0"><strong>What to do:</strong> Check your agency policy. If it counts as a major decline, an Other Follow-Up is due within 2 calendar days. The recert is still due in days 56 to 60.</p></div><div style="background:var(--surface);border:1px solid var(--border);border-radius:8px;padding:12px 16px;margin:10px 0"><p style="margin:0 0 6px"><strong>Scenario 5.</strong> The patient cancels every visit in days 56 to 60.</p><p style="margin:0"><strong>What to do:</strong> Document each attempt. Complete the assessment as soon as the patient allows.</p></div>` },
        { title: 'Regulatory References', content: `<p>This module is based on:</p><ul><li><strong>CMS OASIS-E2 Guidance Manual</strong>, effective April 1, 2026, M0100 coding tips for Recertification, ROC and Other Follow-Up</li><li><strong>42 CFR 484.55</strong> — Comprehensive assessment of patients, including updates at least every 60 days</li></ul><div class="callout">Follow your agency's written policy for assignment of recertification visits and for defining a significant change in condition.</div>` }
      ],
      quiz: [
        { q: 'The recertification OASIS window is:', options: ['Days 1 to 5 of the period', 'Days 30 to 35', 'Days 56 to 60', 'Any time in the last 30 days'], answer: 2, explanation: 'The follow-up assessment for recertification is done in the last 5 days of every 60-day period, which is days 56 to 60.' },
        { q: 'Recertification due dates are counted from:', options: ['The most recent resumption of care date', 'The date of the last physician visit', 'The original Start of Care date', 'The first PT visit after hospitalization'], answer: 2, explanation: 'Unless the patient has been discharged, follow-up due dates are calculated from the original SOC date, not from a ROC date.' },
        { q: 'You discover on day 63 that the recert was missed. What should the agency do?', options: ['Discharge and readmit with a new SOC', 'Skip it, because the window has closed', 'Complete the assessment as soon as possible, record the real date in M0090, and document why it was late', 'Backdate M0090 to day 60'], answer: 2, explanation: 'Do not discharge and readmit. Complete the assessment as soon as the miss is found, enter the actual date in M0090, and document the reason.' },
        { q: 'A patient is discharged from the hospital on day 54 and ROC is done on day 56. What does the manual allow?', options: ['The ROC can serve as both resumption and recertification', 'A ROC and a recert are both always required', 'Neither is required', 'Only a new SOC is allowed'], answer: 0, explanation: 'When the patient is discharged on day 54 or 55 and the ROC is completed on day 56 or 57, the ROC can serve both purposes, provided the physician agrees.' },
        { q: 'Who decides what counts as a significant change in condition for an Other Follow-Up assessment?', options: ['CMS defines it exactly', 'The patient', 'The PTA on the case', 'The agency, in its own written policy'], answer: 3, explanation: 'CMS does not give a written definition of a major decline or improvement. Each agency must define it in its own policy.' }
      ]
    },

    // ─────────────────────────────────────────────
    // 3. OASIS DISCHARGE / TRANSFER
    // ─────────────────────────────────────────────
    {
      id: 'oasis_dc',
      disciplines: ['PT','OT','SLP','RN'],
      track: ['newhire', 'annual'],
      icon: '🏁',
      title: 'OASIS-E2: Discharge, Transfer and Death at Home',
      desc: 'Discharge OASIS timing, who completes it, planned and unplanned discharges, hospital transfers, single-visit episodes and what to document.',
      passScore: 80,
      mins: 18,
      staffTypes: ['clinician', 'owner', 'admin', 'office'],
      slides: [
        { title: 'Three Ways a Quality Episode Ends', content: `<p>A quality episode begins with an SOC or ROC assessment and ends with one of these:</p><ul><li><strong>Discharge (response 9):</strong> the patient leaves the agency for any reason other than an inpatient transfer or death. This includes transfer to another agency or in-home hospice</li><li><strong>Transfer to an inpatient facility (responses 6 and 7):</strong> admitted for 24 hours or longer for a reason other than diagnostic tests</li><li><strong>Death at home (response 8)</strong></li></ul><div class="callout">The discharge OASIS is the final scorecard for the episode. Its function and health status items are compared with the SOC baseline.</div><div style="background:var(--surface);border:1px solid var(--border);border-left:4px solid var(--navy2);border-radius:8px;padding:12px 16px;margin:14px 0"><strong>Examples</strong><ul style="margin:8px 0 0 18px"><li style="margin-bottom:6px"><strong>Discharge (9):</strong> goals are met and the patient is discharged home. Also used when a patient transfers to another home health agency or goes to in-home hospice.</li><li style="margin-bottom:6px"><strong>Transfer (6 or 7):</strong> a patient is admitted to the hospital for a 3-day stay.</li><li style="margin-bottom:6px"><strong>Death at home (8):</strong> a patient dies at home while receiving services, or in the ER before admission.</li></ul></div>` },
        { title: 'Timing and Who Completes It', content: `<ul><li>Discharge, transfer and death at home assessments are due <strong>within 2 calendar days</strong> of the event, or of the agency learning of it</li><li>Discharge needs an <strong>in-person visit</strong>. Transfer and death at home need limited data that can often be gathered by phone</li><li>An RN, PT, OT or SLP completes it. PTAs, COTAs and aides cannot</li><li>If an RN and a therapist both discharge on the same day, the <strong>last qualified clinician to see the patient</strong> does the discharge assessment</li><li>A multidisciplinary case can have several discipline-specific discharges but <strong>only one agency discharge</strong>, and that discharge includes the OASIS</li></ul><div class="callout warn">If you are the last qualified clinician on the case, ask the office early whether you are expected to complete the agency discharge OASIS.</div><div style="background:var(--surface);border:1px solid var(--border);border-left:4px solid var(--navy2);border-radius:8px;padding:12px 16px;margin:14px 0"><strong>Examples</strong><ul style="margin:8px 0 0 18px"><li style="margin-bottom:6px"><strong>Counting 2 days:</strong> the discharge date is Friday. The assessment is due by Sunday.</li><li style="margin-bottom:6px"><strong>Same-day discharges:</strong> an RN sees the patient at 9 a.m. and the PT at 2 p.m., and both are discharging. The PT is the last qualified clinician, so the PT completes the discharge OASIS.</li><li style="margin-bottom:6px"><strong>PTA cannot:</strong> a PTA makes the final visit. A PT or RN still has to complete the discharge assessment, with the PTA sharing observations.</li><li style="margin-bottom:6px"><strong>One agency discharge:</strong> the PT discharges from therapy on Monday while nursing continues until Thursday. The OASIS discharge is done at the agency discharge on Thursday, by the last qualified clinician.</li></ul></div>` },
        { title: 'The Planned Discharge Visit', content: `<p>Treat the discharge visit as a real reassessment.</p><ul><li>Observe function yourself. Do not copy forward the last visit</li><li>Reassess the same M1800 and GG items used at SOC so the comparison is meaningful</li><li>Review each goal and record whether it was met, partly met or not met</li><li>Confirm the home exercise program, safety plan and equipment are in place</li><li>Ask about falls and injuries since SOC/ROC and review records</li><li>Tell the patient and caregiver where to go for further care</li></ul><div class="callout">Discharge goals and outcomes should match what you wrote in your last re-evaluation. If they do not, document why.</div><div style="background:var(--surface);border:1px solid var(--border);border-left:4px solid var(--navy2);border-radius:8px;padding:12px 16px;margin:14px 0"><strong>Examples</strong><ul style="margin:8px 0 0 18px"><li style="margin-bottom:6px"><strong>Goal review:</strong> &ldquo;Goal 1, transfers with supervision: met. Goal 2, walk 150 ft with walker: met. Goal 3, climb 4 steps with rail: partly met, stand-by assist still needed.&rdquo;</li><li style="margin-bottom:6px"><strong>Same items as SOC:</strong> you rated bed mobility and transfers at SOC, so you rate the same activities at discharge to allow a fair comparison.</li><li style="margin-bottom:6px"><strong>Education:</strong> &ldquo;Patient and daughter instructed in HEP, fall-recovery plan, and when to call the physician. Both returned demonstration.&rdquo;</li><li style="margin-bottom:6px"><strong>Referrals:</strong> the patient is referred to outpatient therapy for stair training and is given the number for the local senior center.</li></ul></div>` },
        { title: 'Unplanned Discharge', content: `<p>An unplanned discharge is when care ends and no in-home visit can be made.</p><ul><li>The <strong>last qualified clinician who saw the patient</strong> may complete the discharge assessment from that last visit</li><li>You may add information documented by other agency staff in the <strong>last 5 days the patient received visits</strong>: the last visit date plus the four calendar days before it</li><li>A <strong>dash</strong> is allowed only on items where it is a valid response and no information exists</li><li>For the mood and cognition interview items, if no one completed the interview in that 5-day span, a dash is the only allowed answer</li><li>For items where a dash is not allowed, code from whatever documentation is available</li></ul><div class="callout danger">A dash means no information is available. CMS expects it to be rare. Do not use it to skip an item you could have assessed.</div><div style="background:var(--surface);border:1px solid var(--border);border-left:4px solid var(--navy2);border-radius:8px;padding:12px 16px;margin:14px 0"><strong>Examples</strong><ul style="margin:8px 0 0 18px"><li style="margin-bottom:6px"><strong>Patient moves away suddenly:</strong> the last PT visit was Monday, Nov 10. The last 5 days are Nov 6 to Nov 10. A nurse note from Nov 7 on wound status can be used. The PT completes the rest from the last visit.</li><li style="margin-bottom:6px"><strong>Interview items:</strong> the cognitive and mood interviews were not done in that 5-day span. A dash is the only allowed answer for those items.</li><li style="margin-bottom:6px"><strong>Dash not allowed:</strong> a dash is not valid for an item in the discharge set. Code it from whatever documentation is available.</li></ul></div>` },
        { title: 'Transfers to the Hospital', content: `<ul><li>An <strong>ER visit</strong> or <strong>observation stay</strong> is not a transfer, no matter how long it lasts</li><li><strong>Response 6:</strong> the patient is admitted for 24 hours or longer and the agency expects care to resume</li><li><strong>Response 7:</strong> the patient is admitted and the agency does not expect them to return, so they are discharged</li><li>If the patient comes back, complete a <strong>ROC within 2 calendar days</strong></li><li>A Medicare patient who returns after an inpatient stay that spans the end of the certification period needs a new SOC</li><li>For a patient who goes to a SNF, IRF, LTCH or IPF during a 30-day period, CMS recommends discharging with response 7 and readmitting with a new SOC</li></ul><div class="callout">If you are not sure which response to use, check with the office before submitting. Choosing wrongly can create a ROC requirement that does not exist.</div><div style="background:var(--surface);border:1px solid var(--border);border-left:4px solid var(--navy2);border-radius:8px;padding:12px 16px;margin:14px 0"><strong>Examples</strong><ul style="margin:8px 0 0 18px"><li style="margin-bottom:6px"><strong>Counts as a transfer:</strong> admitted Tuesday evening and kept for 30 hours as an inpatient.</li><li style="margin-bottom:6px"><strong>Does not count:</strong> 10 hours in the ER and then sent home. Also not a transfer: a 2-day observation stay.</li><li style="margin-bottom:6px"><strong>Response 6 or 7:</strong> if the hospital stay is expected to be short and the patient will return, use 6 (not discharged). If the patient is going to a rehab facility long term, use 7 (discharged).</li><li style="margin-bottom:6px"><strong>Return home:</strong> the patient returns on Saturday after a stay and you learn on Monday. The ROC is due within 2 calendar days of the date you learned or the facility discharge, depending on your agency process. Confirm with the office.</li><li style="margin-bottom:6px"><strong>Spans the certification end:</strong> a Medicare patient is hospitalized on day 50 and returns on day 66. A new SOC is required.</li></ul></div>` },
        { title: 'Special Situations', content: `<ul><li><strong>Single-visit episodes:</strong> after only one visit, do not collect or submit a discharge OASIS. Medicare PDGM billing still requires the SOC OASIS</li><li><strong>Payer changes:</strong> ask whether the new payer requires a new SOC. If it does, CMS recommends discharging from the old payer and reassessing under the new one</li><li>Moving from skilled care to a non-OASIS service, such as personal care only, is a good time for a discharge OASIS, though not required</li><li><strong>Original Medicare to Medicare Advantage</strong> does not require a new SOC</li></ul><div class="callout warn">Payer-change rules vary. Ask the agency before you assume a new SOC is or is not needed.</div><div style="background:var(--surface);border:1px solid var(--border);border-left:4px solid var(--navy2);border-radius:8px;padding:12px 16px;margin:14px 0"><strong>Examples</strong><ul style="margin:8px 0 0 18px"><li style="margin-bottom:6px"><strong>One visit only:</strong> a patient is seen once for an evaluation and declines further care. No discharge OASIS. The SOC OASIS is still needed for Medicare PDGM billing.</li><li style="margin-bottom:6px"><strong>Payer change:</strong> a patient moves from Original Medicare to a Medicare Advantage plan. No new SOC is required. Note the payer change at the next time point.</li><li style="margin-bottom:6px"><strong>Reverse:</strong> a patient moves from Medicare Advantage to Original Medicare. A new SOC OASIS is required.</li><li style="margin-bottom:6px"><strong>Skilled to unskilled:</strong> a patient's skilled need ends and only personal care continues. A discharge OASIS at the last skilled visit gives a clean endpoint.</li></ul></div>` },
        { title: 'Discharge Summary and Communication', content: `<ul><li>The discharge OASIS does not replace your discharge summary. Both are required</li><li>The Conditions of Participation set timeframes for sending the discharge or transfer summary to the physician or allowed practitioner. Your agency policy states how it is done</li><li>Make sure the summary matches the OASIS and your last re-evaluation</li><li>Document education given, equipment, community referrals and the reason for discharge</li><li>Tell the supervising PT or case manager when a discharge is planned so the OASIS visit is covered</li></ul><div class="callout">Write the summary the way you would want to read it if you were the receiving physician or therapist.</div><div style="background:var(--surface);border:1px solid var(--border);border-left:4px solid var(--navy2);border-radius:8px;padding:12px 16px;margin:14px 0"><strong>Examples</strong><ul style="margin:8px 0 0 18px"><li style="margin-bottom:6px"><strong>Strong summary:</strong> &ldquo;Admitted [date] for right THA rehab. Discharged [date], goals met. Walks 150 ft with walker, independent in transfers, stairs with rail and stand-by. HEP issued. Follow-up with surgeon [date].&rdquo;</li><li style="margin-bottom:6px"><strong>Matching documents:</strong> the summary says goals met. The last re-evaluation says transfers still need contact guard. Explain the change in the summary.</li><li style="margin-bottom:6px"><strong>Heads-up:</strong> &ldquo;Planning discharge Friday. Can you cover the OASIS visit if I am out?&rdquo; A message like this to the case manager prevents a missed assessment.</li></ul></div>` },
        { title: 'Worked Examples', content: `<p>Try each scenario before reading the answer.</p><div style="background:var(--surface);border:1px solid var(--border);border-radius:8px;padding:12px 16px;margin:10px 0"><p style="margin:0 0 6px"><strong>Scenario 1.</strong> The RN discharges at 9 a.m. and you discharge at 2 p.m.</p><p style="margin:0"><strong>What to do:</strong> You are the last qualified clinician, so you complete the discharge OASIS.</p></div><div style="background:var(--surface);border:1px solid var(--border);border-radius:8px;padding:12px 16px;margin:10px 0"><p style="margin:0 0 6px"><strong>Scenario 2.</strong> The patient is admitted to the hospital for 30 hours and the family plans to move out of state.</p><p style="margin:0"><strong>What to do:</strong> Complete a transfer assessment. If the agency does not expect the patient back, use response 7.</p></div><div style="background:var(--surface);border:1px solid var(--border);border-radius:8px;padding:12px 16px;margin:10px 0"><p style="margin:0 0 6px"><strong>Scenario 3.</strong> The patient has a 2-day observation stay and comes home.</p><p style="margin:0"><strong>What to do:</strong> It is not a transfer. Care continues, with no transfer or ROC OASIS.</p></div><div style="background:var(--surface);border:1px solid var(--border);border-radius:8px;padding:12px 16px;margin:10px 0"><p style="margin:0 0 6px"><strong>Scenario 4.</strong> A patient is seen once and declines further care.</p><p style="margin:0"><strong>What to do:</strong> No discharge OASIS. The SOC OASIS is still needed for Medicare PDGM billing.</p></div><div style="background:var(--surface);border:1px solid var(--border);border-radius:8px;padding:12px 16px;margin:10px 0"><p style="margin:0 0 6px"><strong>Scenario 5.</strong> A patient moves away without notice. The last PT visit was Nov 10.</p><p style="margin:0"><strong>What to do:</strong> Complete the discharge from your last visit and use information from Nov 6 to Nov 10 by other staff. Use dashes only where allowed.</p></div>` },
        { title: 'Regulatory References', content: `<p>This module is based on:</p><ul><li><strong>CMS OASIS-E2 Guidance Manual</strong>, effective April 1, 2026: Chapter 1 time points, conventions and unplanned discharge guidance, and M0100 coding tips</li><li><strong>42 CFR 484.55</strong> — Comprehensive assessment of patients</li><li><strong>42 CFR 484.110</strong> — Clinical records, including discharge and transfer summaries</li></ul><div class="callout">Check your agency's discharge policy for who completes the final visit and how summaries are sent.</div>` }
      ],
      quiz: [
        { q: 'A discharge OASIS is due within:', options: ['24 hours', '2 calendar days of the discharge or of learning of it', '5 calendar days', '30 days'], answer: 1, explanation: 'Discharge, transfer and death at home assessments are due within 2 calendar days of the event, or of the agency learning of it.' },
        { q: 'A patient spends 10 hours in the ER and is sent home. Which is correct?', options: ['Complete a transfer OASIS', 'Complete a ROC OASIS', 'Discharge the patient', 'It is not a transfer, because ER visits and observation stays do not count'], answer: 3, explanation: 'Time in the ER or an observation stay does not meet the definition of a transfer to an inpatient facility, regardless of duration.' },
        { q: 'A PT and an RN both discharge a patient on the same day. Who completes the discharge OASIS?', options: ['The RN always', 'The PT always', 'The last qualified clinician to see the patient', 'The PTA'], answer: 2, explanation: 'When both are scheduled the same day, the last qualified clinician to see the patient is responsible for the discharge comprehensive assessment.' },
        { q: 'A patient is discharged after only one visit. What is correct for the OASIS?', options: ['A discharge OASIS is not collected, though the SOC OASIS is still needed to bill Medicare PDGM', 'A discharge OASIS is always required', 'No OASIS of any kind is ever needed', 'A transfer OASIS must be completed'], answer: 0, explanation: 'After a single-visit quality episode a discharge OASIS should not be collected or submitted, but billing Medicare PDGM still requires the SOC OASIS.' },
        { q: 'In an unplanned discharge, information from other staff may be used if it was documented in:', options: ['The last 5 days the patient received visits', 'The first 5 days of the episode', 'The last 30 days', 'Any prior visit'], answer: 0, explanation: 'The last 5 days that visits were received means the date of the last visit plus the four preceding calendar days.' }
      ]
    },

    // ─────────────────────────────────────────────
    // 4. THERAPY RE-EVALUATION
    // ─────────────────────────────────────────────
    {
      id: 'therapy_reeval',
      disciplines: ['PT','OT','SLP'],
      track: ['newhire', 'annual'],
      icon: '📊',
      title: 'Therapy Re-Evaluation and 30-Day Reassessment',
      desc: 'When a qualified therapist must reassess, what a defensible re-evaluation contains, and how it connects to OASIS, the plan of care and physician communication.',
      passScore: 80,
      mins: 18,
      staffTypes: ['clinician', 'owner', 'admin', 'office'],
      slides: [
        { title: 'What a Re-Evaluation Does', content: `<p>A re-evaluation is a qualified therapist's reassessment of function against the plan of care. It answers three questions:</p><ul><li>Is the patient improving, plateauing or declining?</li><li>Is skilled therapy still reasonable and necessary?</li><li>Do the goals, frequency and interventions still fit?</li></ul><div class="callout">A re-evaluation is a clinical document first. It is also one of the strongest pieces of evidence that care is skilled, effective and still needed.</div><div style="background:var(--surface);border:1px solid var(--border);border-left:4px solid var(--navy2);border-radius:8px;padding:12px 16px;margin:14px 0"><strong>Examples</strong><ul style="margin:8px 0 0 18px"><li style="margin-bottom:6px"><strong>Improving:</strong> gait distance rises from 40 ft to 120 ft over three weeks. Continue skilled therapy and raise the goals.</li><li style="margin-bottom:6px"><strong>Plateau:</strong> three weeks of the same numbers with no change in strategy. Reassess, adjust the plan or discuss discharge.</li><li style="margin-bottom:6px"><strong>Declining:</strong> balance score worsens after a new medication. Reassess and notify the physician.</li></ul></div>` },
        { title: 'The 30-Day Reassessment Rule', content: `<p>For each therapy discipline provided, a <strong>qualified therapist</strong> must reassess the patient's function <strong>at least once every 30 days</strong>.</p><ul><li>The therapist provides the ordered service, functionally reassesses, and <strong>compares results with prior measurements</strong></li><li>The results and whether therapy is effective must be documented</li><li><strong>Only a qualified therapist</strong>, not an assistant, may perform the reassessment</li><li>In multi-discipline cases, each discipline reassesses against its own goals</li><li>Timing is a clinical judgment. It does not have to fall exactly on day 30</li></ul><div class="callout warn">This 30-day rule replaced the older rule that tied reassessments to the 13th and 19th visits. Do not use visit counts as your trigger.</div><div style="background:var(--surface);border:1px solid var(--border);border-left:4px solid var(--navy2);border-radius:8px;padding:12px 16px;margin:14px 0"><strong>Examples</strong><ul style="margin:8px 0 0 18px"><li style="margin-bottom:6px"><strong>Compliant:</strong> evaluation on Oct 1, 9 visits, PT reassesses and documents on Oct 28.</li><li style="margin-bottom:6px"><strong>Not compliant:</strong> the PTA provides all visits for 35 days with no PT visit and no reassessment.</li><li style="margin-bottom:6px"><strong>Two disciplines:</strong> PT and OT are both ordered. PT reassesses against PT goals and OT against OT goals. Each does its own within 30 days.</li><li style="margin-bottom:6px"><strong>Clinical timing:</strong> the PT reassesses on day 24 because the patient had a fall. That also satisfies the 30-day rule for that period.</li></ul></div>` },
        { title: 'What a Defensible Re-Evaluation Contains', content: `<ul><li><strong>Objective measures</strong> repeated from the initial evaluation so the comparison is direct: ROM, strength, balance score, gait distance and device, transfer assist level, timed tests</li><li><strong>Status of each goal:</strong> met, progressing, partly met or not met, with the evidence</li><li><strong>Effectiveness statement:</strong> what has changed because of therapy and why continued skilled care is needed</li><li><strong>Barriers:</strong> pain, cognition, caregiver support, home setup, adherence</li><li><strong>Updated plan:</strong> revised goals, frequency and duration, home exercise program, equipment, discharge plan</li><li><strong>Falls and safety</strong> since the last assessment</li></ul><div class="callout">Use the same tests each time. A new measure with no baseline cannot show progress.</div><div style="background:var(--surface);border:1px solid var(--border);border-left:4px solid var(--navy2);border-radius:8px;padding:12px 16px;margin:14px 0"><strong>Examples</strong><ul style="margin:8px 0 0 18px"><li style="margin-bottom:6px"><strong>Measures compared:</strong> a short table or list works well:<br>Gait: 40 ft with walker, contact guard at eval; 120 ft with walker, supervision now.<br>Sit to stand: moderate assist at eval; supervision now.<br>Timed test: same test, same setup, same device.</li><li style="margin-bottom:6px"><strong>Goal status:</strong> &ldquo;Goal 1: met. Goal 2: progressing, 60% of target. Goal 3: not met, limited by pain.&rdquo;</li><li style="margin-bottom:6px"><strong>Effectiveness statement:</strong> &ldquo;Skilled PT has produced measurable gains in gait and transfers. Patient requires skilled guarding and cueing to progress safely to stairs.&rdquo;</li><li style="margin-bottom:6px"><strong>Plan update:</strong> &ldquo;Frequency 2x/week for 3 weeks, then 1x/week. New goal: climb 4 steps with a rail and supervision.&rdquo;</li></ul></div>` },
        { title: 'Beyond the Calendar: Other Triggers', content: `<p>Reassess sooner when something changes.</p><ul><li>A <strong>fall, hospitalization or new diagnosis</strong></li><li>A <strong>significant improvement or decline</strong> in function</li><li>New orders or a change in the physician's plan</li><li>Goals met earlier than expected</li><li>A <strong>plateau</strong> with no measurable gain over several visits</li><li>Patient or caregiver concerns that change the plan</li></ul><div class="callout warn">If a PTA notices one of these triggers, the PTA tells the supervising PT. The PTA does not change goals or the plan of care.</div><div style="background:var(--surface);border:1px solid var(--border);border-left:4px solid var(--navy2);border-radius:8px;padding:12px 16px;margin:14px 0"><strong>Examples</strong><ul style="margin:8px 0 0 18px"><li style="margin-bottom:6px"><strong>Fall:</strong> a patient falls Thursday and reports new hip pain. The PT reassesses at the next visit instead of waiting for day 30.</li><li style="margin-bottom:6px"><strong>Fast progress:</strong> goals are met by week 3 of a planned 6-week plan. Reassess, update goals or plan discharge.</li><li style="margin-bottom:6px"><strong>New diagnosis:</strong> a patient has a new neurological diagnosis. Reassess and update the plan.</li><li style="margin-bottom:6px"><strong>PTA report:</strong> &ldquo;Patient needed more help with transfers on 3 of the last 4 visits and reports new knee swelling.&rdquo; The PTA sends that to the supervising PT the same day.</li></ul></div>` },
        { title: 'Connecting the Re-Evaluation to OASIS', content: `<ul><li>A re-evaluation is not automatically an OASIS time point</li><li><strong>Other Follow-Up (M0100 response 5)</strong> is required within 2 calendar days of a significant change in condition, as your agency policy defines it</li><li>The <strong>recertification OASIS</strong> falls on days 56 to 60 and is a separate requirement. A re-evaluation in that window can support it</li><li>After a qualifying hospital stay, a <strong>ROC assessment</strong> is due within 2 calendar days</li><li>Under PDGM, an Other Follow-Up completed before the next 30-day period starts can change the functional impairment level for that period's claim</li></ul><div class="callout">When your re-evaluation shows a major change, tell the case manager the same day so the OASIS and the claim stay in step.</div><div style="background:var(--surface);border:1px solid var(--border);border-left:4px solid var(--navy2);border-radius:8px;padding:12px 16px;margin:14px 0"><strong>Examples</strong><ul style="margin:8px 0 0 18px"><li style="margin-bottom:6px"><strong>Routine re-eval:</strong> the PT reassesses on day 30 with stable status. No OASIS follow-up is triggered by that alone.</li><li style="margin-bottom:6px"><strong>Significant change:</strong> the patient has a stroke and function drops sharply. Under agency policy that is a significant change, so an Other Follow-Up OASIS is due within 2 calendar days.</li><li style="margin-bottom:6px"><strong>Recert window:</strong> the PT does the day 30 and later day 58 re-evaluations. The day 58 reassessment helps support the recertification OASIS.</li><li style="margin-bottom:6px"><strong>Hospital return:</strong> the patient comes home after an inpatient stay. A ROC is due within 2 calendar days.</li></ul></div>` },
        { title: 'Communicating the Results', content: `<ul><li>Send the re-evaluation and any <strong>plan-of-care changes</strong> to the physician or allowed practitioner and get orders signed</li><li>Give the PTA clear written direction on updated goals, precautions and progression</li><li>Tell the patient and caregiver what has changed and why</li><li>If goals are met or progress has stopped, discuss discharge or a change in approach</li><li>Match the language of your re-evaluation to the OASIS and the daily notes</li></ul><div class="callout">Daily notes that contradict the re-evaluation are a common reason for denials. Review PTA notes after a re-evaluation to confirm they reflect the new plan.</div><div style="background:var(--surface);border:1px solid var(--border);border-left:4px solid var(--navy2);border-radius:8px;padding:12px 16px;margin:14px 0"><strong>Examples</strong><ul style="margin:8px 0 0 18px"><li style="margin-bottom:6px"><strong>To the physician:</strong> &ldquo;Re-evaluation completed [date]. Gait improved from 40 to 120 ft. Requesting order to continue PT 2x/week for 3 weeks and add stair training.&rdquo;</li><li style="margin-bottom:6px"><strong>To the PTA:</strong> &ldquo;Updated goals attached. Progress stair training with rail, guard on descent. Hold resisted knee extension until pain is under 4/10.&rdquo;</li><li style="margin-bottom:6px"><strong>To the patient:</strong> &ldquo;You are walking farther. Next we focus on stairs so you can get to the bedroom safely.&rdquo;</li></ul></div>` },
        { title: 'Common Mistakes', content: `<ul><li>Letting an assistant perform the 30-day reassessment</li><li>Copying the last evaluation forward with a few words changed</li><li>Using measures that cannot be compared with the baseline</li><li>No effectiveness statement, only "continue plan of care"</li><li>Goals that never change even though the patient has moved</li><li>Missing a significant change that should have triggered Other Follow-Up</li><li>Updating the plan but not telling the PTA</li></ul><div class="callout danger">"Patient tolerated treatment well" and "continue per plan" are not re-evaluations. Reviewers expect measurable change or a clear reason for no change.</div><div style="background:var(--surface);border:1px solid var(--border);border-left:4px solid var(--navy2);border-radius:8px;padding:12px 16px;margin:14px 0"><strong>Examples</strong><ul style="margin:8px 0 0 18px"><li style="margin-bottom:6px"><strong>Weak:</strong> &ldquo;Patient tolerated treatment well. Continue plan of care.&rdquo;<br><strong>Stronger:</strong> &ldquo;Gait improved from 40 ft to 120 ft with walker. Needs skilled guarding for turns. Continue 2x/week for 3 weeks to progress to stairs.&rdquo;</li><li style="margin-bottom:6px"><strong>Copy-forward:</strong> the new evaluation reads the same as last month, down to the same numbers. Measure again and write what you actually found.</li><li style="margin-bottom:6px"><strong>Wrong person:</strong> a PTA writes and signs a reassessment. It is invalid for the 30-day rule. A PT must perform it.</li><li style="margin-bottom:6px"><strong>Goals never change:</strong> the goal says &ldquo;walk 25 ft&rdquo; while the patient already walks 150 ft. Update it.</li></ul></div>` },
        { title: 'Worked Examples', content: `<p>Try each scenario before reading the answer.</p><div style="background:var(--surface);border:1px solid var(--border);border-radius:8px;padding:12px 16px;margin:10px 0"><p style="margin:0 0 6px"><strong>Scenario 1.</strong> Eval Oct 1. It is Nov 5 and only the PTA has seen the patient.</p><p style="margin:0"><strong>What to do:</strong> The 30-day reassessment is late. The PT should reassess now and document why timing slipped.</p></div><div style="background:var(--surface);border:1px solid var(--border);border-radius:8px;padding:12px 16px;margin:10px 0"><p style="margin:0 0 6px"><strong>Scenario 2.</strong> Numbers have been the same for three weeks and the note says &ldquo;continue plan of care.&rdquo;</p><p style="margin:0"><strong>What to do:</strong> Reassess. Change the approach, discuss the plateau with the physician, or plan discharge.</p></div><div style="background:var(--surface);border:1px solid var(--border);border-radius:8px;padding:12px 16px;margin:10px 0"><p style="margin:0 0 6px"><strong>Scenario 3.</strong> A PTA writes a progress summary and signs it as a reassessment.</p><p style="margin:0"><strong>What to do:</strong> It does not meet the rule. A PT must perform and document the reassessment.</p></div><div style="background:var(--surface);border:1px solid var(--border);border-radius:8px;padding:12px 16px;margin:10px 0"><p style="margin:0 0 6px"><strong>Scenario 4.</strong> A patient has a stroke on day 20.</p><p style="margin:0"><strong>What to do:</strong> Reassess promptly. Check your agency policy for an Other Follow-Up OASIS within 2 calendar days.</p></div><div style="background:var(--surface);border:1px solid var(--border);border-radius:8px;padding:12px 16px;margin:10px 0"><p style="margin:0 0 6px"><strong>Scenario 5.</strong> Goals say &ldquo;walk 25 ft&rdquo; but the patient walks 150 ft.</p><p style="margin:0"><strong>What to do:</strong> Update the goals, record the change, and send the revised plan to the physician and PTA.</p></div>` },
        { title: 'Regulatory References', content: `<p>This module is based on:</p><ul><li><strong>42 CFR 409.44</strong> and <strong>Medicare Benefit Policy Manual, Chapter 7</strong> — skilled therapy requirements and reassessment, as updated by the CY 2015 Home Health final rule</li><li><strong>CMS OASIS-E2 Guidance Manual</strong>, M0100 coding tips for Other Follow-Up and ROC</li></ul><div class="callout">State practice acts and your agency's policies may add requirements. Follow whichever standard is stricter.</div>` }
      ],
      quiz: [
        { q: 'How often must a qualified therapist functionally reassess a home health therapy patient?', options: ['At the 13th and 19th visits', 'At least once every 30 days', 'Only at recertification', 'Only at discharge'], answer: 1, explanation: 'The visit-based schedule was replaced by a requirement for a functional reassessment at least once every 30 days by a qualified therapist.' },
        { q: 'Who may perform the 30-day reassessment?', options: ['A qualified therapist, not an assistant', 'A PTA under general supervision', 'An aide', 'Any clinician on the case'], answer: 0, explanation: 'Only a qualified therapist may perform the functional reassessment. An assistant cannot.' },
        { q: 'Which statement best shows that skilled therapy is effective?', options: ['Patient tolerated treatment well', 'Continue plan of care', 'Gait improved from 40 feet with standby assist to 120 feet with a rolling walker and supervision', 'Patient is motivated'], answer: 2, explanation: 'Comparable, measurable change from the baseline shows effectiveness. General statements do not.' },
        { q: 'A PTA notices the patient fell twice this week and is declining. What should the PTA do?', options: ['Adjust the goals', 'Continue the plan and mention it next month', 'Tell the supervising PT so the PT can reassess', 'Complete an Other Follow-Up OASIS'], answer: 2, explanation: 'The PTA reports the change to the supervising PT. The PT decides on reassessment, plan changes and any OASIS follow-up.' },
        { q: 'A re-evaluation shows a major improvement. What is the OASIS implication?', options: ['None, a re-evaluation is never an OASIS time point', 'A new SOC is always required', 'A discharge OASIS is always required', 'Check whether your agency policy treats it as a significant change that needs an Other Follow-Up within 2 calendar days'], answer: 3, explanation: 'A re-evaluation is not automatically an OASIS time point, but a significant change as defined by agency policy requires an Other Follow-Up (M0100 response 5) within 2 calendar days.' }
      ]
    },

    // ─────────────────────────────────────────────
    // 5. DAILY VISIT NOTES
    // ─────────────────────────────────────────────
    {
      id: 'daily_note',
      disciplines: ['PT','PTA','OT','COTA','SLP'],
      track: ['newhire', 'annual'],
      icon: '🗒️',
      title: 'Daily Visit Note Documentation (PT and PTA)',
      desc: 'What a complete daily note contains, how to show skilled need, objective data and response, PTA scope, and what reviewers check.',
      passScore: 80,
      mins: 16,
      staffTypes: ['clinician', 'owner', 'admin', 'office'],
      slides: [
        { title: 'The Job of a Daily Note', content: `<p>A daily note proves that a skilled service was delivered, that it was needed, and that it moved the patient toward a goal.</p><ul><li><strong>Payment:</strong> notes support the visits the agency bills</li><li><strong>Continuity:</strong> the next clinician picks up where you left off</li><li><strong>Safety:</strong> changes in condition are caught early</li><li><strong>Legal record:</strong> if it is not documented, a reviewer treats it as not done</li></ul><div class="callout">Write each note as if a reviewer who has never met the patient will read only that note.</div><div style="background:var(--surface);border:1px solid var(--border);border-left:4px solid var(--navy2);border-radius:8px;padding:12px 16px;margin:14px 0"><strong>Examples</strong><ul style="margin:8px 0 0 18px"><li style="margin-bottom:6px"><strong>Reviewer's view:</strong> a reviewer reads one note out of context. They should be able to tell who was treated, what you did, why it needed a skilled clinician, how the patient responded, and what comes next.</li><li style="margin-bottom:6px"><strong>Continuity:</strong> a covering PTA reads your note and knows the patient needs contact guard on stairs and a cue for step length.</li></ul></div>` },
        { title: 'Required Elements of Every Note', content: `<ul><li>Patient name or ID, date of service, <strong>time in and time out</strong></li><li><strong>Signature with credentials</strong>, completed within agency policy</li><li>Reference to the <strong>PT evaluation or plan of care</strong> the visit is following</li><li>The <strong>specific skilled interventions</strong> performed</li><li>Objective data: what you measured or observed</li><li>The patient's <strong>response</strong> to treatment and any limiting factors</li><li>Education given and the home exercise program status</li><li>Plan for the next visit</li></ul><div class="callout warn">Visit frequency and duration must match the order and plan of care. A visit that does not match needs an explanation in the note.</div><div style="background:var(--surface);border:1px solid var(--border);border-left:4px solid var(--navy2);border-radius:8px;padding:12px 16px;margin:14px 0"><strong>Examples</strong><ul style="margin:8px 0 0 18px"><li style="margin-bottom:6px"><strong>Time:</strong> &ldquo;Time in 10:05, time out 10:50.&rdquo;</li><li style="margin-bottom:6px"><strong>Signature:</strong> &ldquo;Jane Doe, PTA, signed 10/26/2026 11:15.&rdquo;</li><li style="margin-bottom:6px"><strong>Plan reference:</strong> &ldquo;Treatment per PT evaluation of 10/20/2026, goals 1 and 3.&rdquo;</li><li style="margin-bottom:6px"><strong>Frequency mismatch:</strong> the order is 3x/week but you made 2 visits. &ldquo;Third visit missed, patient hospital appointment. PT notified.&rdquo;</li><li style="margin-bottom:6px"><strong>Plan for next visit:</strong> &ldquo;Next visit: progress stair training to 4 steps with rail.&rdquo;</li></ul></div>` },
        { title: 'Showing Skilled Need', content: `<p>Reviewers ask why a skilled clinician was needed instead of the patient or a caregiver.</p><p><strong>Weak:</strong> "Therapeutic exercises and gait training performed."</p><p><strong>Strong:</strong> "Gait training 150 ft with rolling walker, minimal assist at first, progressed to stand-by assist. Verbal cues needed for step length and walker position. Balance challenged on uneven surface with close guarding due to loss of balance on the left turn. Patient could not safely progress without clinician guarding and cues."</p><ul><li>Name the intervention</li><li>Give sets, reps, distance, device and assist level</li><li>State the cueing or skilled judgment used</li><li>Tie it to a goal on the plan of care</li></ul><div class="callout">If a caregiver could have done what you describe, say what skilled judgment made your visit necessary.</div><div style="background:var(--surface);border:1px solid var(--border);border-left:4px solid var(--navy2);border-radius:8px;padding:12px 16px;margin:14px 0"><strong>Examples</strong><ul style="margin:8px 0 0 18px"><li style="margin-bottom:6px"><strong>Transfer training. Weak:</strong> &ldquo;Transfer training performed.&rdquo;<br><strong>Strong:</strong> &ldquo;Sit to stand and bed to chair x5. Verbal cues for hand placement and forward trunk lean. Min assist at first, stand-by on final 2 reps. Patient unsafe without clinician guarding due to dizziness on rising.&rdquo;</li><li style="margin-bottom:6px"><strong>Balance. Weak:</strong> &ldquo;Balance exercises.&rdquo;<br><strong>Strong:</strong> &ldquo;Standing balance on foam with eyes open 3 x 30 sec. Contact guard, one loss of balance posteriorly corrected by clinician. Progressed from firm surface this visit.&rdquo;</li><li style="margin-bottom:6px"><strong>HEP education. Weak:</strong> &ldquo;Reviewed HEP.&rdquo;<br><strong>Strong:</strong> &ldquo;Instructed in HEP: heel raises, sit to stand 2 x 10. Patient returned demonstration with cues for knee alignment. Handout issued, daughter present and understood.&rdquo;</li><li style="margin-bottom:6px"><strong>Pain management. Weak:</strong> &ldquo;Patient in pain.&rdquo;<br><strong>Strong:</strong> &ldquo;Pain 6/10 left knee at start, 3/10 after gentle ROM and positioning. Treatment modified to avoid resisted extension.&rdquo;</li></ul></div>` },
        { title: 'Objective Data and Patient Response', content: `<ul><li>Include <strong>at least one measurable data point</strong> that can be compared with the last visit: distance, assist level, balance score, repetitions, pain rating, vital signs</li><li>Describe how the patient <strong>responded</strong>: symptoms, fatigue, safety, change in performance</li><li>State progress plainly: <strong>progressing, plateau or declining</strong></li><li>Make sure your words match your data. "Significant improvement" next to unchanged numbers invites questions</li></ul><div class="callout danger">Never write a note ahead of time or copy a prior note forward. Each note must describe what happened in that visit.</div><div style="background:var(--surface);border:1px solid var(--border);border-left:4px solid var(--navy2);border-radius:8px;padding:12px 16px;margin:14px 0"><strong>Examples</strong><ul style="margin:8px 0 0 18px"><li style="margin-bottom:6px"><strong>Gait:</strong> &ldquo;120 ft with rolling walker, supervision. Last visit 90 ft.&rdquo;</li><li style="margin-bottom:6px"><strong>Vitals:</strong> &ldquo;BP 142/84, HR 88 before; 150/86, HR 102 after 3 min walking. Patient reports mild shortness of breath, resolved with rest in 2 min.&rdquo;</li><li style="margin-bottom:6px"><strong>Response:</strong> &ldquo;Patient fatigued after 2 sets, required 90 sec rest breaks, completed session.&rdquo;</li><li style="margin-bottom:6px"><strong>Progress label:</strong> &ldquo;Progressing: gait distance up 30 ft since last visit.&rdquo;</li><li style="margin-bottom:6px"><strong>Words not matching data:</strong> &ldquo;Significant improvement in balance&rdquo; next to a balance score unchanged from last week. Fix one or the other.</li></ul></div>` },
        { title: 'Homebound Status and Safety', content: `<ul><li>Document what supports <strong>homebound status</strong>: the effort needed to leave home, the device or help required, and the reason it is taxing</li><li>Ask at every visit about <strong>falls, near-falls, new pain or new symptoms</strong> and record the answer</li><li>Document safety education and caregiver training</li><li>Record changes in the home, equipment needs and caregiver availability</li></ul><div class="callout">A fall or ER visit between visits affects the OASIS. Report it to the supervising PT or case manager the same day.</div><div style="background:var(--surface);border:1px solid var(--border);border-left:4px solid var(--navy2);border-radius:8px;padding:12px 16px;margin:14px 0"><strong>Examples</strong><ul style="margin:8px 0 0 18px"><li style="margin-bottom:6px"><strong>Homebound support:</strong> &ldquo;Patient requires rolling walker and stand-by assist to leave the home. Walking to the car 40 ft causes shortness of breath and requires a rest. Leaving home is a taxing effort.&rdquo;</li><li style="margin-bottom:6px"><strong>Fall question:</strong> &ldquo;Patient denies falls or near-falls since last visit. Reports new dizziness on standing this morning.&rdquo;</li><li style="margin-bottom:6px"><strong>Safety education:</strong> &ldquo;Instructed on removing throw rugs and using night lights. Daughter agrees to move the rugs today.&rdquo;</li><li style="margin-bottom:6px"><strong>Caregiver change:</strong> &ldquo;Spouse now at work during the day. Patient alone from 8 a.m. to 4 p.m.&rdquo;</li></ul></div>` },
        { title: 'PTA Scope and When to Escalate', content: `<p>PTAs deliver treatment under the direction of the supervising PT, and document it.</p><ul><li>A PTA <strong>may not</strong> complete the evaluation, the 30-day reassessment, OASIS, or change goals or the plan of care</li><li>Supervision requirements come from your state practice act and your agency policy</li></ul><p><strong>Tell the supervising PT when you see:</strong></p><ul><li>A major improvement or decline</li><li>A fall, ER visit or hospitalization</li><li>No progress, or goals nearly met</li><li>A need for a new order, equipment or reassessment</li><li>Anything in the note that conflicts with the evaluation or OASIS</li></ul><div class="callout warn">Escalating is part of the PTA's job. A note that records a major change but is never passed on to the PT is a compliance problem.</div><div style="background:var(--surface);border:1px solid var(--border);border-left:4px solid var(--navy2);border-radius:8px;padding:12px 16px;margin:14px 0"><strong>Examples</strong><ul style="margin:8px 0 0 18px"><li style="margin-bottom:6px"><strong>Message to the PT:</strong> &ldquo;Mr. R. had a fall last night, no injury, but needed more help with transfers today. Is a reassessment needed?&rdquo;</li><li style="margin-bottom:6px"><strong>Goals nearly met:</strong> &ldquo;Patient has reached the 150 ft goal for 3 visits in a row. Please review goals or discharge plan.&rdquo;</li><li style="margin-bottom:6px"><strong>What the PTA does not do:</strong> the patient wants stairs added to the plan. The PTA does not add goals. The PTA tells the PT.</li><li style="margin-bottom:6px"><strong>Conflict found:</strong> the OASIS says independent walking, but the PTA sees contact guard each visit. The PTA reports it to the PT.</li></ul></div>` },
        { title: 'What Reviewers Check', content: `<p>Expect your notes to be audited against questions like these:</p><ul><li>Are the time in and out, signature and credentials present?</li><li>Does the visit match the ordered frequency and duration?</li><li>Are the skilled interventions named, with specifics?</li><li>Does it explain why skilled care was needed?</li><li>Does each intervention tie to a goal?</li><li>Is there a measurable data point and a documented response?</li><li>Does it support homebound status and ask about falls?</li><li>Does it conflict with the evaluation, OASIS or earlier notes?</li><li>Were red flags passed to the supervising PT?</li></ul><div class="callout">Use these questions as a checklist before you sign each note.</div><div style="background:var(--surface);border:1px solid var(--border);border-left:4px solid var(--navy2);border-radius:8px;padding:12px 16px;margin:14px 0"><strong>Examples</strong><ul style="margin:8px 0 0 18px"><li style="margin-bottom:6px"><strong>Passes:</strong> time in and out, signature, specific interventions, one measurable value, response, tie to goal 2, next visit plan.</li><li style="margin-bottom:6px"><strong>Needs correction:</strong> no time out, vague intervention, no data, no link to a goal.</li><li style="margin-bottom:6px"><strong>Escalate to PT:</strong> a note says the patient fell and was sent to the ER. The reviewer sends it to the supervising PT the same day.</li></ul></div>` },
        { title: 'Worked Examples', content: `<p>Try each scenario before reading the answer.</p><div style="background:var(--surface);border:1px solid var(--border);border-radius:8px;padding:12px 16px;margin:10px 0"><p style="margin:0 0 6px"><strong>Scenario 1.</strong> Your draft: &ldquo;Therapeutic exercise performed. Patient did well.&rdquo;</p><p style="margin:0"><strong>What to do:</strong> Rewrite with the exercises, sets, reps, assist level, cueing and a measurable result, and tie it to a goal.</p></div><div style="background:var(--surface);border:1px solid var(--border);border-radius:8px;padding:12px 16px;margin:10px 0"><p style="margin:0 0 6px"><strong>Scenario 2.</strong> The patient mentions a fall last night during your visit.</p><p style="margin:0"><strong>What to do:</strong> Document it, report it to the supervising PT or case manager the same day, and note any injury or symptoms.</p></div><div style="background:var(--surface);border:1px solid var(--border);border-radius:8px;padding:12px 16px;margin:10px 0"><p style="margin:0 0 6px"><strong>Scenario 3.</strong> You are a PTA and the patient asks to add stair goals.</p><p style="margin:0"><strong>What to do:</strong> Do not change goals. Tell the supervising PT.</p></div><div style="background:var(--surface);border:1px solid var(--border);border-radius:8px;padding:12px 16px;margin:10px 0"><p style="margin:0 0 6px"><strong>Scenario 4.</strong> Your note says &ldquo;significant improvement&rdquo; but the balance score is unchanged.</p><p style="margin:0"><strong>What to do:</strong> Correct the wording or the data so they agree.</p></div><div style="background:var(--surface);border:1px solid var(--border);border-radius:8px;padding:12px 16px;margin:10px 0"><p style="margin:0 0 6px"><strong>Scenario 5.</strong> You made 2 of 3 ordered visits this week.</p><p style="margin:0"><strong>What to do:</strong> Document the reason for the missed visit in the note and tell the supervising PT or case manager.</p></div>` },
        { title: 'Regulatory References', content: `<p>This module is based on:</p><ul><li><strong>Medicare Benefit Policy Manual, Chapter 7</strong> — home health services and skilled therapy requirements</li><li><strong>42 CFR 484.110</strong> — Condition of Participation: clinical records</li><li><strong>42 CFR 409.44</strong> — skilled services requirements for therapy</li></ul><div class="callout">Payers and agencies may require additional elements. Follow the stricter standard and your agency's note templates.</div>` }
      ],
      quiz: [
        { q: 'Which note entry best supports skilled need?', options: ['Exercises performed. Patient did well.', 'Gait training 150 ft with rolling walker, progressed from min assist to stand-by assist with cues for step length and walker position', 'Continue plan of care', 'Patient is motivated and cooperative'], answer: 1, explanation: 'Specific interventions, measurable data, level of assistance and the skilled cueing show why a skilled clinician was needed.' },
        { q: 'Which of these may a PTA NOT do?', options: ['Document the treatment given', 'Report a change in condition to the supervising PT', 'Perform the 30-day functional reassessment', 'Instruct the patient in the home exercise program'], answer: 2, explanation: 'The 30-day reassessment, evaluation, OASIS and plan-of-care changes belong to the PT. The PTA documents treatment and reports changes.' },
        { q: 'During a visit the patient mentions a fall last night. What should you do?', options: ['Document it and tell the supervising PT or case manager the same day', 'Leave it out because it was not during the visit', 'Wait for the next re-evaluation', 'Change the goals yourself'], answer: 0, explanation: 'A fall affects the plan of care and may affect the OASIS. Document it and report it the same day.' },
        { q: 'A note says "significant improvement in balance" but the balance score is unchanged. What is the problem?', options: ['None, because notes are subjective', 'The words do not match the data', 'The note is too short', 'The time in and out is missing'], answer: 1, explanation: 'Words must match measurable data. A conflict between them is a common audit finding.' },
        { q: 'Which is NOT a required element of a daily note?', options: ['Time in and time out', 'Signature with credentials', 'The patient\'s full billing history', 'The specific skilled interventions performed'], answer: 2, explanation: 'Billing history does not belong in the daily note. Time, signature, interventions, objective data and response do.' }
      ]
    }
  ];

  CLINICAL_MODULES.forEach(function (m) {
    if (!MODULES.find(function (x) { return x.id === m.id; })) MODULES.push(m);
  });
})();
